const REVIEW_API='https://zah-public-editor.zahmediaofficial.workers.dev/api/testimonials';
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
async function setupForm(){
 const form=document.getElementById('review-form'),project=document.getElementById('review-project'),grid=document.getElementById('review-photos'),more=document.getElementById('more-photos'),status=document.getElementById('review-status');
 const r=await fetch('/portfolio/collections.json?v=reviews');if(!r.ok)throw Error('Projects could not load. Please refresh.');const collections=await r.json();
 project.replaceChildren(new Option('Choose your project or service',''));for(const g of collections)project.add(new Option(g.title,g.slug));
 for(const [key,label]of Object.entries({'wedding':'Wedding photography','event':'Event photography','portrait':'Portrait photography','graduation':'Graduation portraits','corporate':'Corporate photography'}))project.add(new Option(label+' · private or unlisted shoot','service-'+key));
 let photos=[],shown=0;
 function showPhotos(){for(const p of photos.slice(shown,shown+6)){const label=el('label');label.className='review-photo-choice';const image=el('img');image.src='/portfolio/'+p.src;image.alt=p.alt||'Project photograph';image.loading='lazy';const radio=el('input');radio.type='radio';radio.name='photoId';radio.value=p.id;radio.setAttribute('aria-label','Choose '+image.alt);label.append(image,radio);grid.append(label);}shown+=6;more.hidden=shown>=photos.length;}
 function update(){grid.replaceChildren();photos=collections.find(g=>g.slug===project.value)?.photos||[];shown=0;form.querySelector('input[name=photoId][value=""]').checked=true;showPhotos();}
 project.addEventListener('change',update);more.addEventListener('click',showPhotos);const requested=new URLSearchParams(location.search).get('project');if(collections.some(g=>g.slug===requested))project.value=requested;update();
 form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const button=document.getElementById('review-submit');button.disabled=true;status.textContent='Sending your testimonial…';const data=new FormData(form);try{const response=await fetch(REVIEW_API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:data.get('name'),email:data.get('email'),projectId:data.get('projectId'),text:data.get('text'),handle:data.get('handle'),photoId:data.get('photoId'),website:data.get('website'),consent:data.get('consent')==='on'})});const result=await response.json();if(!response.ok)throw Error(result.error||'Could not submit your testimonial.');form.reset();update();status.textContent='Thank you. Your testimonial was received privately and is awaiting ZAH Media’s approval.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
}
async function showReviews(){const status=document.getElementById('review-status'),list=document.getElementById('published-reviews');const response=await fetch(REVIEW_API);if(!response.ok)throw Error('Client stories are temporarily unavailable.');const {reviews}=await response.json();for(const r of reviews){const article=el('article');article.className='review-story';if(r.photo?.src?.startsWith('https://zahmediastudio.com/portfolio/assets/')){const img=el('img');img.src=r.photo.src;img.alt=r.photo.alt||'Client photograph';img.loading='lazy';article.append(img);}article.append(el('blockquote',r.text),el('p',r.name),el('small',[r.project,r.handle].filter(Boolean).join(' · ')));list.append(article);}status.textContent=reviews.length?'':'Client stories will appear here once they have been approved. Have we worked together? We’d love to hear your experience.';}
(document.getElementById('review-form')?setupForm():showReviews()).catch(e=>document.getElementById('review-status').textContent=e.message);
